import react from 'react';
import styles from './styles/ModTicModStyles.module.css';

function ModifyTicketModal({closeModifyTicketModal, ticket}){
    async function modifyTicket(event) {
        event.preventDefault();

        const titlee = document.getElementById("title").value;
        const descriptionn = document.getElementById("description").value;


    }


    return(
        <div className={styles.modalBackground}>
           <div className={styles.modalContainer}>
            <div className={styles.title}>
                <h1>Hibajegy módosítása</h1>
            </div>
            <div className={styles.body}>
                <input className={styles.inputBox} defaultValue={ticket?.title} />
                <select
                        id="urgentid"
                        className={styles.inputBox}
                        defaultValue={ticket?.urgentid}
                    >
                        <option value="1">Nem s</option>
                        <option value="2">Sűrgős</option>
                        <option value="3">Kritikus</option>
                        <option value="10">Nem tudom</option>
                    </select>
                <textarea className={styles.inputBox} defaultValue={ticket?.description} />
            </div>
            <div className={styles.footer}>
                <button className={styles.closeBtn} onClick={() => closeModifyTicketModal(false)}>Mégse</button>
                <button className={styles.saveBtn}>Mentés</button>
            </div>
           </div>
        </div>
    )
}

export default ModifyTicketModal;
